import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { defineConfig, loadEnv } from 'vite';
import react from '@vitejs/plugin-react';

const frontendDirectory = path.dirname(fileURLToPath(import.meta.url));

export default defineConfig(({ mode }) => {
  const env = loadEnv(mode, frontendDirectory, 'VITE_');
  let address = env.VITE_CONTRACT_ADDRESS || '';

  // Prefer an explicit environment override; otherwise use the deployment record
  // generated by the local Hardhat deployment script.
  const deploymentFile = path.resolve(
    frontendDirectory,
    '../contracts/deployments/localhost/insurance-contract.json',
  );
  if (!address && existsSync(deploymentFile)) {
    try {
      const deployment = JSON.parse(readFileSync(deploymentFile, 'utf8'));
      if (deployment.network === 'localhost' && Number(deployment.chainId) === 31337) {
        address = deployment.address || '';
      }
    } catch {
      // The application shows a setup message when no valid deployment is available.
    }
  }

  return {
    plugins: [react()],
    define: {
      'import.meta.env.VITE_CONTRACT_ADDRESS': JSON.stringify(address),
    },
    build: {
      rollupOptions: {
        output: {
          manualChunks(id) {
            if (id.includes('/node_modules/@mui/') || id.includes('/node_modules/@emotion/')) return 'ui-vendor';
            if (id.includes('/node_modules/react/') || id.includes('/node_modules/react-dom/') || id.includes('/node_modules/scheduler/')) return 'react-vendor';
            if (id.includes('/node_modules/ethers/') || id.includes('/node_modules/@ethersproject/') || id.includes('/node_modules/@noble/')) return 'web3-vendor';
            return undefined;
          },
        },
      },
    },
  };
});
